UPDATE permissions SET group_code='ACCOUNTING',feature_code='ACC',operation_code='CREATE',name_ar='Accounts - Create',name_en='Accounts - Create',display_order=320,is_sensitive=0 WHERE permission_code='ACC.CREATE';
